export const RLM_EXEC_DESCRIPTION = [
    "Execute JavaScript in an isolated Deno Worker whose generated-code realm has no filesystem, network, environment, subprocess, or FFI permissions.",
    "The trusted transport runner has narrowly scoped read access only to its fixed Worker entry module. All sandbox API calls are async — always await them.",
    "API: llm(prompt) -> string (stateless child LLM); llm.batch(prompts) -> string[] (strict: 1-16 prompts, rejects if any child fails); llm.batchSettled(prompts) -> Array<{ok:true,value:string}|{ok:false,error:{code,message}}> (same budgets/order, preserves successful siblings when a child fails). The host runs at most 4 children concurrently and queues the rest.",
    "Context API: context.files(query) -> string[]; context.read(path) -> string; context.readMany(paths) -> Array<{path, content?, error?}>; context.grep(pattern) -> Array<{path, line, text}>.",
    "Working-memory API: memory.get(key) -> JSON value or undefined; memory.set(key, value) -> void; memory.delete(key) -> boolean; memory.keys() -> string[]. Values must be JSON-serializable. Memory survives multiple rlm_exec calls in the same root user turn, is inaccessible to child LLMs, and is destroyed when the authoritative user turn changes or the host session is deleted.",
    "Budgets per execution: max 16 child prompts, max 4 concurrent child calls, max 32 context operations, max 64 memory operations, max 64 paths per readMany, prompts up to 32768 chars, total context data 1 MiB, per-file reads 128 KiB, grep 200 matches, files 4096 paths, runtime timeout 120s.",
    "Budgets per user turn: max 12 rlm_exec, max 32 child calls, max 96 context operations, max 2 MiB context data, max 128 memory operations, max 128 memory entries, max 131072 serialized JSON characters per memory value, max 524288 key-plus-serialized-value characters total stored memory, max 180s rlm_exec wall time.",
    "Children are stateless semantic workers. By default they inherit the parent model/variant; trusted host configuration may instead route them to a fixed child model. Generated JavaScript cannot select the child model. Children do not receive repository context, prior conversation, working memory, or RLM context APIs. Include all task-specific data a child needs directly in its prompt.",
    "Prefer rlm_map for standard repository partition/map/merge work and rlm_verify for conservative false-positive filtering; use rlm_exec only when custom control flow is required.",
    "Example: const paths = await context.files(\"src/\"); const files = await context.readMany(paths.slice(0, 4)); const summaries = await llm.batch(files.map(function (f) { return \"Summarize: \" + f.content; })); await memory.set(\"summaries\", summaries); return { count: paths.length, stored: summaries.length };",
].join(" ");
export const RLM_MAP_DESCRIPTION = [
    "Structured repository semantic map. Prefer this over handwritten rlm_exec JavaScript for standard file fan-out workloads.",
    "The trusted runtime lists and reads bounded repository files, partitions them deterministically, sends each partition to an isolated child, and validates a versioned structured result contract before returning it to the root.",
    "fanout defaults to 4 and is bounded to 1-16; actual child concurrency remains capped at 4. partition=round_robin preserves the original behavior; partition=balanced_chars greedily balances source characters while remaining deterministic.",
    "failureMode=strict is the default and rejects on any child failure. failureMode=settled preserves successful partitions and reports bounded partitionErrors; it does not create extra child budget.",
    "output=text returns one result per partition. output=path_list accepts only JSON path arrays and validates each selected path against the exact partition the child saw. output=candidate_bundle adds trusted source text for accepted candidates plus a conservative verification contract.",
    "Candidate bundles are presumptively valid: root verification should reject only clear false positives and keep uncertainty. Candidate source handoff is hard-bounded so rlm_map cannot silently reload the whole repository into root context.",
    "Repository source is framed as untrusted data in every structured child prompt. Oversized partitions fail before the first child call with guidance to increase fanout or narrow the query. Child responses are bounded before parsing (32768 chars for text; 16384 for path_list/candidate_bundle), and malformed or oversized structured responses are never automatically repaired with another model call.",
    "The structured path compiles to a fixed trusted JavaScript template and executes through the same zero-permission Worker, context policy, child routing, turn governor, cancellation, budgets, and telemetry as rlm_exec.",
    "An exact repeated rlm_map request from the same authoritative assistant boundary reuses the first successfully completed result instead of launching another child fan-out. Replay metadata does not duplicate provider-usage telemetry; raw rlm_exec is never deduplicated.",
].join(" ");
export const RLM_VERIFY_DESCRIPTION = [
    "Conservative structured candidate verifier. Use after a path-producing scan when false positives should be removed without allowing a second classifier to invent or expand candidates.",
    "Input candidates are presumptively valid repository paths. The trusted runtime re-reads their source through bounded context authority and runs an asymmetric two-pass filter: a first child pass may nominate clear false positives, then an independent confirmation pass re-checks only those provisional removals.",
    "A path is removed only when both passes support removal. Uncertainty always means KEEP. An allowed exception must be proven by the semantic role of the mutated field/control state itself; a suggestive value or bare name such as pending/loading/done/status is not sufficient proof. Children cannot add candidates, remove a path outside their source partition, or broaden filesystem authority.",
    "At most 64 candidate paths are accepted per call. First-pass fanout defaults to 4 and is bounded to 1-8 with at most 4 children concurrently; confirmation uses at most the same number of additional child calls, so one rlm_verify remains within the 16-call execution budget. A 16-child rlm_map plus a maximally budgeted rlm_verify still fits the existing 32-child per-turn budget.",
    "failureMode=strict rejects on child/provider or structured-validation failure. failureMode=settled preserves every candidate from a failed/malformed first-pass or confirmation partition, because failed verification is uncertainty rather than evidence for removal.",
    "Child responses are bounded to 16384 characters before JSON parsing. The independent confirmation pass is intentional verification semantics, not an automatic repair/retry: malformed or oversized output is never repaired by asking a model to fix its formatting.",
    "The same zero-permission Worker, context policy, child routing, cancellation, budgets, telemetry, and same-boundary duplicate suppression used by rlm_map apply here.",
].join(" ");
